
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_revtca_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_revtca", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.669158051797877e-02, -6.615429796474101e-02, -6.535800648761191e-02, -6.416358480968150e-02, -6.234330517387202e-02, -5.951477447106978e-02, -5.503346410870988e-02, -4.789423440568358e-02, -3.708289361187411e-02, -2.394543107282887e-02, -1.723672722070773e-02, -3.629692640809156e-02, -3.943200845674876e-02, -2.906121287657106e-02, -1.436235220610864e-02, -3.450948625843648e-03, -2.672502248023528e-04, -4.428697512657990e-06, -9.415509105584201e-09, -1.537343010182501e-12]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


